  const milliseconds=performance.now()-start;
  if(result.status!==0)throw new Error(JSON.stringify({executable,args,status:result.status,stdout:result.stdout,stderr:result.stderr,error:result.error?.message}));
  return {milliseconds,stdout:result.stdout,stderr:result.stderr};
};
const tracked=checked("git",["ls-files","-z"],root).stdout.split("\0").filter(Boolean);
const files=[];
