const write=checked(oxfmt,["-c",oxConfigPath,"--write",...files],repoDirs.oxfmt);
const repositoryDifferences=[];
for(const file of files){const before=await fs.readFile(path.join(root,file),"utf8");const after=await fs.readFile(path.join(repoDirs.oxfmt,file),"utf8");if(before!==after)repositoryDifferences.push({file,before,after});}
const fixtureDir=path.join(work,"mixed-fixtures");
await fs.mkdir(fixtureDir,{recursive:true});
await fs.symlink(path.join(audit.work,"prettier/node_modules"),path.join(fixtureDir,"node_modules"));
await fs.writeFile(path.join(fixtureDir,"prettier.config.mjs"),`export {default} from ${JSON.stringify(runtime)};\n`);
for(const test of audit.results){await fs.mkdir(path.dirname(path.join(fixtureDir,test.filename)),{recursive:true});await fs.writeFile(path.join(fixtureDir,test.filename),test.baseline.stdout);}
const fixtureFiles=audit.results.map(x=>x.filename);
