const command=(tool,executable,args,cwd)=>({tool,commands:[{executable,args,cwd}],samples:[]});
const scenarios=[
  {id:"repository-check",fileCount:files.length,bytes:(await Promise.all(files.map(async x=>(await fs.stat(path.join(root,x))).size))).reduce((a,b)=>a+b,0),files,runs:[
    command("prettier",process.execPath,[prettierCli,"--check",...files],repoDirs.prettier),
    command("prettier-cached",process.execPath,[prettierCli,"--check",...pcache,...files],repoDirs.prettier),
    command("oxfmt",oxfmt,["-c",oxConfigPath,"--check",...files],repoDirs.oxfmt),
    command("bun-existing","bun",["fmt","--no-script","--check",...files],repoDirs.bun),
  ]},
  {id:"one-file-check",fileCount:1,files:["index.mjs"],runs:[
    command("prettier",process.execPath,[prettierCli,"--check","index.mjs"],repoDirs.prettier),
    command("prettier-cached",process.execPath,[prettierCli,"--check",...pcache,"index.mjs"],repoDirs.prettier),
    command("oxfmt",oxfmt,["-c",oxConfigPath,"--check","index.mjs"],repoDirs.oxfmt),
    command("bun-existing","bun",["fmt","--no-script","--check","index.mjs"],repoDirs.bun),
  ]},
  {id:"mixed-plugin-check",fileCount:fixtureFiles.length,files:fixtureFiles,legacyFiles,nativeFiles,runs:[
    command("prettier",process.execPath,[prettierCli,"--check",...fixtureFiles],fixtureDir),
    command("bun-existing","bun",["fmt","--no-script","--check",...fixtureFiles],fixtureDir),
    {tool:"oxfmt-prettier-hybrid",commands:[{executable:oxfmt,args:["-c",oxConfigPath,"--check",...nativeFiles],cwd:fixtureDir},{executable:process.execPath,args:[prettierCli,"--check",...legacyFiles],cwd:fixtureDir}],samples:[]},
  ]},
];
